'use strict';
// UI state only; each new query/page performs a new server request, with no historical fallback.
const catalog={items:[],mode:'combined',sort:'',q:'',start:0,total:0,hasMore:false,status:'idle',fetchedAt:null};let catalogRequest=0;
function catalogView(){const labels={combined:'热销促销',deals:'正在促销',top:'当前热销',all:'全部游戏'};return head('游戏雷达','把热度和价格一起看，下一款值得玩的游戏就在这里。')+`<div class="catalog-tabs" role="group" aria-label="游戏列表类型">${Object.entries(labels).map(([key,label])=>`<button class="filter-chip ${catalog.mode===key?'active':''}" data-catalog-mode="${key}" aria-pressed="${catalog.mode===key}">${label}</button>`).join('')}</div><form id="catalog-search" class="catalog-tools"><label class="sr-only" for="catalog-query">搜索 Steam 游戏</label><input id="catalog-query" value="${e(catalog.q)}" placeholder="搜索游戏名称，中英文均可" maxlength="80"><button class="small-btn" type="submit">搜索</button><label class="sr-only" for="catalog-sort">游戏排序</label><select id="catalog-sort"><option value="" ${!catalog.sort?'selected':''}>${['top','combined'].includes(catalog.mode)?'来源热销顺序':'来源默认顺序'}</option><option value="Price_ASC" ${catalog.sort==='Price_ASC'?'selected':''}>本页价格从低到高</option><option value="Price_DESC" ${catalog.sort==='Price_DESC'?'selected':''}>本页价格从高到低</option></select><button type="button" class="small-btn" data-catalog-refresh>↻</button></form><div class="catalog-summary" role="status">${catalog.status==='loading'?'正在连接 Steam 国区商店…':catalog.status==='error'?'来源暂不可用，点击刷新重试。':`来源匹配 ${e(catalog.total)} 项 · 本页 ${catalog.items.length} 款 · ${e(sourceTime(catalog.fetchedAt))} 获取`}</div><p class="catalog-note">${['top','combined'].includes(catalog.mode)&&!catalog.sort?'热销次序来自当前国区商店筛选结果，不代表具体销量。':'按商店当前筛选展示；价格排序作用于本页，来源可能含推荐项目。'} 每页最多 25 款；价格与购买以商店为准。</p><div class="catalog-list">${catalog.items.map((d,i)=>`<a class="catalog-game" href="${e(d.url)}" target="_blank" rel="noopener"><span class="catalog-number">${String(catalog.start+i+1).padStart(2,'0')}</span>${imageBlock(d,'catalog-cover')}<div class="catalog-copy"><h3>${e(d.game)}</h3><span>STEAM / ${d.currency==='CNY'?'国区 CNY':'商店条目'}</span></div><div class="catalog-price">${d.discount?'<span class="deal-off">-'+e(d.discount)+'%</span>':''}<div>${d.original?'<s>'+e(d.original)+'</s>':''}<strong>${e(d.price)}</strong></div></div></a>`).join('')}</div>${!catalog.items.length&&catalog.status==='ready'?'<p class="live-empty">没有符合条件的游戏，试试更短的名称或其他分类。</p>':''}<div class="catalog-pages"><button class="small-btn" data-catalog-page="prev" ${catalog.start===0||catalog.status==='loading'?'disabled':''}>← 上一页</button><span>第 ${Math.floor(catalog.start/25)+1} 页</span><button class="small-btn" data-catalog-page="next" ${!catalog.hasMore||catalog.status==='loading'?'disabled':''}>下一页 →</button></div>`}
async function loadCatalog(start=0){const request=++catalogRequest;catalog.start=start;catalog.status='loading';catalog.items=[];catalog.hasMore=false;if(route==='deals')render(route,false);try{const query=new URLSearchParams({mode:catalog.mode,sort:catalog.sort,q:catalog.q,start:String(start),request:String(Date.now())});const response=await fetch('/api/catalog?'+query,{cache:'no-store',signal:AbortSignal.timeout(16000)});const data=await response.json();if(request!==catalogRequest)return;if(!response.ok||!Array.isArray(data.items))throw Error('Source unavailable');Object.assign(catalog,{items:data.items,total:data.total,hasMore:data.hasMore,status:'ready',fetchedAt:data.fetchedAt})}catch{if(request!==catalogRequest)return;catalog.status='error';catalog.items=[];catalog.total=0}if(route==='deals')render(route,false)}
function newsRoute(n){return n.appid?'news/steam/'+n.appid+'/'+n.id:'news/community/'+n.url.match(/articles\/(\d+)/)?.[1]}
function findStory(r){const parts=r.split('/');return parts[1]==='steam'?SNAPSHOT.news.find(n=>String(n.appid)===parts[2]&&n.id===parts[3]):SNAPSHOT.community.find(n=>n.url.endsWith('/'+parts[2]))}
function newsReader(r){const story=findStory(r);if(!story){const loading=SNAPSHOT[(r.includes('/steam/')?'news':'community')+'Status']==='loading';return head(loading?'正在打开新闻':'本次来源列表未收录这篇新闻',loading?'正在获取来源提供的正文…':'可返回发现页重新获取；不使用旧快照补位。')+'<button class="small-btn" data-go="home">← 返回发现</button>'}return `<button class="subtle-btn" data-go="home">← 返回发现</button><article class="article news-reader"><span class="eyebrow">${e(story.source)} · ${e(story.game)}</span><h1>${e(story.title)}</h1><div class="article-meta">${e(story.author||'来源编辑')} · ${e(story.date)}<span>站外来源同步</span></div><div class="reader-source"><span>以下为来源接口 / RSS 提供的内容，图片与观点归原作者。</span><a href="${e(story.url)}" target="_blank" rel="noopener">查看原文 ↗</a></div><div id="reader-body" class="reader-body"></div><div class="reader-bottom"><button class="small-btn" data-go="home">返回新闻列表</button><a class="small-btn" href="${e(story.url)}" target="_blank" rel="noopener">来源提供的完整版本 ↗</a></div></article>`}
function bbcodeHTML(text){let html=e(text.replace(/\{STEAM_CLAN_IMAGE\}/g,'https://clan.fastly.steamstatic.com/images'));html=html.replace(/\[img src=&quot;([^\[]+?)&quot;\]\[\/img\]/gi,'<img src="$1">').replace(/\[img\]([^\[]+)\[\/img\]/gi,'<img src="$1">').replace(/\[url=([^\]]+)\]([\s\S]*?)\[\/url\]/gi,'<a href="$1">$2</a>');const tags={p:'p',b:'strong',i:'em',u:'u',h1:'h2',h2:'h2',h3:'h3',list:'ul',olist:'ol',quote:'blockquote',table:'table',tr:'tr',td:'td',th:'th'};for(const [from,to]of Object.entries(tags))html=html.replace(new RegExp('\\['+from+'\\]','gi'),'<'+to+'>').replace(new RegExp('\\[/'+from+'\\]','gi'),'</'+to+'>');return html.replace(/\[\*\]/g,'<br>• ').replace(/\[\/?(?:previewyoutube|previewyoutube=)[^\]]*\]/gi,'').replace(/\n/g,'<br>')}
function safeReaderHTML(body,format){const source=new DOMParser().parseFromString(format==='bbcode'?bbcodeHTML(body):body,'text/html');const output=document.createElement('div'),allowed=new Set(['P','BR','H1','H2','H3','H4','STRONG','B','EM','I','U','UL','OL','LI','BLOCKQUOTE','TABLE','THEAD','TBODY','TR','TH','TD','FIGURE','FIGCAPTION','DIV','SPAN','HR','PRE','CODE']);function copy(node,parent){if(node.nodeType===3){parent.append(document.createTextNode(node.textContent));return}if(node.nodeType!==1||['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','FORM','INPUT','BUTTON','SVG','MATH','LINK','META'].includes(node.tagName))return;if(node.tagName==='IMG'){let url;try{url=new URL(node.getAttribute('src'));if(url.protocol!=='https:')return}catch{return}const box=document.createElement('div');box.className='reader-image';const img=document.createElement('img');img.src='/api/media?url='+encodeURIComponent(url.href);img.dataset.originalImage=url.href;img.alt=node.getAttribute('alt')||'来源正文配图';img.loading='lazy';img.referrerPolicy='no-referrer';box.append(img);parent.append(box);return}if(node.tagName==='A'){let url;try{url=new URL(node.getAttribute('href'));if(!['https:','http:'].includes(url.protocol))throw Error()}catch{[...node.childNodes].forEach(n=>copy(n,parent));return}const a=document.createElement('a');a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';[...node.childNodes].forEach(n=>copy(n,a));parent.append(a);return}const target=allowed.has(node.tagName)?document.createElement(node.tagName.toLowerCase()):parent;[...node.childNodes].forEach(n=>copy(n,target));if(target!==parent)parent.append(target)}[...source.body.childNodes].forEach(n=>copy(n,output));return output}
function mountDiscovery(r){if(r==='deals'&&window.offlineSelectedGame){catalog.q=window.offlineSelectedGame;window.offlineSelectedGame='';catalog.mode='all';catalog.status='idle';}if(r==='deals'&&catalog.status==='idle')queueMicrotask(()=>loadCatalog());if(r.startsWith('news/')){const n=findStory(r),host=document.querySelector('#reader-body');if(n&&host){if(n.body)host.replaceChildren(safeReaderHTML(n.body,n.bodyFormat));else host.textContent='来源本次未提供正文，可以查看原文。'}}}
document.addEventListener('click',event=>{const mode=event.target.closest('[data-catalog-mode]');if(mode){catalog.mode=mode.dataset.catalogMode;catalog.sort='';catalog.q='';loadCatalog(0)}const page=event.target.closest('[data-catalog-page]');if(page){loadCatalog(Math.max(0,catalog.start+(page.dataset.catalogPage==='next'?25:-25)));document.querySelector('.page-heading')?.scrollIntoView({block:'start'})}if(event.target.closest('[data-catalog-refresh]'))loadCatalog(catalog.start)});
document.addEventListener('submit',event=>{if(event.target.id!=='catalog-search')return;event.preventDefault();catalog.q=document.querySelector('#catalog-query').value.trim();if(catalog.q&&catalog.mode==='top')catalog.mode='all';if(catalog.q&&catalog.mode==='combined')catalog.mode='deals';loadCatalog(0)});
document.addEventListener('change',event=>{if(event.target.id==='catalog-sort'){catalog.sort=event.target.value;if(catalog.sort&&catalog.mode==='top')catalog.mode='all';if(catalog.sort&&catalog.mode==='combined')catalog.mode='deals';loadCatalog(0)}});
mountDiscovery(route);if(route.startsWith('news/'))render(route,false);
